#include "no5_platform.hpp"
#include "lodepng.h"
#define STB_TRUETYPE_IMPLEMENTATION
#include "stb_truetype.h"

namespace {
thread_local std::vector<unsigned char> fontBytes;
thread_local stbtt_fontinfo fontInfo;
thread_local bool fontReady=false;
float FontScale(const wxFont& f){if(!fontReady)throw std::runtime_error("No5 bundled font not initialized");return stbtt_ScaleForPixelHeight(&fontInfo,f.GetPointSize()*4.0f/3.0f);}
std::vector<int> Codepoints(const wxString& s){std::vector<int> result;for(size_t i=0;i<s.size();){unsigned char c=s[i++];int cp=c,n=0;if(c>=0xf0){cp=c&7;n=3;}else if(c>=0xe0){cp=c&15;n=2;}else if(c>=0xc0){cp=c&31;n=1;}for(int j=0;j<n&&i<s.size();j++)cp=(cp<<6)|(s[i++]&63);result.push_back(cp);}return result;}
}
void no5PlatformLoadFont(const std::string& file){std::ifstream f(file,std::ios::binary);fontBytes.assign(std::istreambuf_iterator<char>(f),{});if(fontBytes.empty()||!stbtt_InitFont(&fontInfo,fontBytes.data(),stbtt_GetFontOffsetForIndex(fontBytes.data(),0)))throw std::runtime_error("No5 bundled font load failed");fontReady=true;}
bool no5PlatformValidateFont(const std::vector<unsigned char>& bytes){if(bytes.size()<12)return false;stbtt_fontinfo info;int offset=stbtt_GetFontOffsetForIndex(bytes.data(),0);return offset>=0&&stbtt_InitFont(&info,bytes.data(),offset);}
void no5PlatformInstallFont(std::vector<unsigned char> bytes){fontBytes.swap(bytes);stbtt_InitFont(&fontInfo,fontBytes.data(),stbtt_GetFontOffsetForIndex(fontBytes.data(),0));fontReady=true;}
bool wxImage::LoadFile(const wxString& path,int){std::vector<unsigned char> pixels;unsigned ww,hh;unsigned err=lodepng::decode(pixels,ww,hh,std::string(path));if(err)return false;w=ww;h=hh;rgb.resize(size_t(w)*h*3);alpha.resize(size_t(w)*h);for(size_t i=0;i<alpha.size();i++){std::copy_n(&pixels[4*i],3,&rgb[3*i]);alpha[i]=pixels[4*i+3];}return true;}
void wxImage::SetRGB(const wxRect& r,int red,int green,int blue){for(int y=std::max(0,r.y);y<std::min(h,r.y+r.height);y++)for(int x=std::max(0,r.x);x<std::min(w,r.x+r.width);x++){size_t p=(size_t(y)*w+x)*3;rgb[p]=red;rgb[p+1]=green;rgb[p+2]=blue;}}
wxImage& wxImage::Rescale(int ww,int hh,int){if(ww<=0||hh<=0||!IsOk())throw std::runtime_error("invalid symbol dimensions");wxImage out(ww,hh);out.mask=mask;out.masked=masked;if(HasAlpha())out.InitAlpha();for(int y=0;y<hh;y++)for(int x=0;x<ww;x++){int sx=std::min(w-1,int((x+0.5)*w/ww)),sy=std::min(h-1,int((y+0.5)*h/hh));size_t a=size_t(sy)*w+sx,b=size_t(y)*ww+x;std::copy_n(&rgb[a*3],3,&out.rgb[b*3]);if(HasAlpha())out.alpha[b]=alpha[a];}*this=std::move(out);return *this;}
wxBitmap wxBitmap::GetSubBitmap(wxRect r)const{if(!IsOk()||r.x<0||r.y<0||r.width<=0||r.height<=0||r.width>image->w||r.height>image->h||r.x>image->w-r.width||r.y>image->h-r.height)throw std::runtime_error("symbol atlas bounds: "+std::to_string(r.x)+","+std::to_string(r.y)+","+std::to_string(r.width)+","+std::to_string(r.height)+" within "+std::to_string(image?image->w:0)+","+std::to_string(image?image->h:0));wxImage out(r.width,r.height);if(image->HasAlpha())out.InitAlpha();for(int y=0;y<r.height;y++)for(int x=0;x<r.width;x++){size_t a=size_t(y+r.y)*image->w+x+r.x,b=size_t(y)*r.width+x;std::copy_n(&image->rgb[a*3],3,&out.rgb[b*3]);if(image->HasAlpha())out.alpha[b]=image->alpha[a];}out.mask=image->mask;out.masked=image->masked;return wxBitmap(out);}
void wxBitmap::SetMask(wxMask* m){if(image)image->SetMaskColour(m->color.Red(),m->color.Green(),m->color.Blue());delete m;}
void wxDC::Pixel(int x,int y,wxColour c){if(!target||x<0||y<0||x>=target->w||y>=target->h)return;size_t p=(size_t(y)*target->w+x)*3;if(pixelOwners&&(p/3>=pixelOwners->size()||int((*pixelOwners)[p/3])!=pixelOwner+1))return;int a=c.Alpha();target->rgb[p]=(c.Red()*a+target->rgb[p]*(255-a)+127)/255;target->rgb[p+1]=(c.Green()*a+target->rgb[p+1]*(255-a)+127)/255;target->rgb[p+2]=(c.Blue()*a+target->rgb[p+2]*(255-a)+127)/255;if(target->HasAlpha())target->alpha[p/3]=a+(target->alpha[p/3]*(255-a)+127)/255;}
void wxDC::Span(int x0,int x1,int y,wxColour c){if(!target||y<0||y>=target->h)return;for(int x=std::max(0,x0);x<std::min(target->w,x1);x++)Pixel(x,y,c);}
void wxDC::Clear(){if(!target)return;target->SetRGB(wxRect(0,0,target->w,target->h),background.GetColour().Red(),background.GetColour().Green(),background.GetColour().Blue());if(target->HasAlpha())std::fill(target->alpha.begin(),target->alpha.end(),background.GetColour().Alpha());}
void wxDC::DrawPoint(int x,int y){Pixel(x,y,pen.GetColour());}
void wxDC::DrawLine(int x0,int y0,int x1,int y1){
 Bounds(x0,y0);Bounds(x1,y1);
 if(!target||pen.GetWidth()<=0)return;
 // Clip before iterating: a panned chart can have extremely distant vertices.
 double a=0,b=1,dx=double(x1)-x0,dy=double(y1)-y0;int margin=pen.GetWidth()+1;
 auto clip=[&](double p,double q){if(!p)return q>=0;double r=q/p;if(p<0){if(r>b)return false;a=std::max(a,r);}else{if(r<a)return false;b=std::min(b,r);}return true;};
 if(!clip(-dx,x0+margin)||!clip(dx,target->w+margin-x0)||!clip(-dy,y0+margin)||!clip(dy,target->h+margin-y0))return;
 int x=std::lround(x0+a*dx),y=std::lround(y0+a*dy),ex=std::lround(x0+b*dx),ey=std::lround(y0+b*dy),ddx=std::abs(ex-x),ddy=std::abs(ey-y),sx=x<ex?1:-1,sy=y<ey?1:-1,err=ddx-ddy,step=0;
 wxDash* dash;int nd=pen.GetDashes(&dash),cycle=0;for(int i=0;i<nd;i++)cycle+=dash[i]*pen.GetWidth();
 while(true){bool show=true;if(pen.GetStyle()==wxPENSTYLE_SHORT_DASH)show=step%10<6;else if(nd&&cycle){int p=step%cycle,j=0;while(j<nd&&p>=dash[j]*pen.GetWidth()){p-=dash[j]*pen.GetWidth();j++;}show=j%2==0;}if(show){int r=pen.GetWidth()/2;for(int yy=y-r;yy<y-r+pen.GetWidth();yy++)Span(x-r,x-r+pen.GetWidth(),yy,pen.GetColour());}if(x==ex&&y==ey)break;int e2=err*2;if(e2>-ddy){err-=ddy;x+=sx;}if(e2<ddx){err+=ddx;y+=sy;}step++;}
}
void wxDC::DrawRectangle(int x,int y,int w,int h){if(brush.GetStyle()!=wxBRUSHSTYLE_TRANSPARENT)for(int yy=std::max(0,y);target&&yy<std::min(target->h,y+h);yy++)Span(x,x+w,yy,brush.GetColour());DrawLine(x,y,x+w-1,y);DrawLine(x+w-1,y,x+w-1,y+h-1);DrawLine(x+w-1,y+h-1,x,y+h-1);DrawLine(x,y+h-1,x,y);}
void wxDC::DrawCircle(int x,int y,int r){if(r<=0)return;if(brush.GetStyle()!=wxBRUSHSTYLE_TRANSPARENT)for(int yy=std::max(-r,-y);target&&yy<=std::min(r,target->h-y-1);yy++){int xx=int(std::sqrt(double(r)*r-double(yy)*yy));Span(x-xx,x+xx+1,y+yy,brush.GetColour());}DrawEllipticArc(x-r,y-r,r*2,r*2,0,360);}
void wxDC::DrawEllipticArc(int x,int y,int w,int h,double start,double end){if(end<=start)end+=360;int n=std::max(2,int((end-start)*std::max(w,h)/180));double oldx=0,oldy=0;for(int i=0;i<=n;i++){double angle=(start+(end-start)*i/n)*3.141592653589793/180,xx=x+w/2.0+std::cos(angle)*w/2,yy=y+h/2.0-std::sin(angle)*h/2;if(i)DrawLine(std::lround(oldx),std::lround(oldy),std::lround(xx),std::lround(yy));oldx=xx;oldy=yy;}}
void wxDC::DrawPolygon(int n,const wxPoint* points,int dx,int dy,int){if(!target||n<3)return;if(brush.GetStyle()!=wxBRUSHSTYLE_TRANSPARENT){int lo=target->h,hi=0;for(int i=0;i<n;i++){lo=std::min(lo,points[i].y+dy);hi=std::max(hi,points[i].y+dy);}std::vector<double> hits;for(int y=std::max(0,lo);y<std::min(target->h,hi);y++){hits.clear();for(int i=0,j=n-1;i<n;j=i++){double ay=points[j].y+dy,by=points[i].y+dy;double py=y+0.5;if((ay<=py&&by>py)||(by<=py&&ay>py))hits.push_back(points[j].x+dx+(py-ay)*(points[i].x-points[j].x)/(by-ay));}std::sort(hits.begin(),hits.end());for(size_t i=0;i+1<hits.size();i+=2)Span(int(std::ceil(hits[i]-0.5)),int(std::ceil(hits[i+1]-0.5)),y,brush.GetColour());}}for(int i=0,j=n-1;i<n;j=i++)DrawLine(points[j].x+dx,points[j].y+dy,points[i].x+dx,points[i].y+dy);}
void wxDC::DrawBitmap(const wxBitmap& bmp,int x,int y,bool mask){if(!bmp.IsOk()||!target)return;auto& im=*bmp.image;for(int yy=std::max(0,-y);yy<std::min(im.h,target->h-y);yy++)for(int xx=std::max(0,-x);xx<std::min(im.w,target->w-x);xx++){size_t p=(size_t(yy)*im.w+xx);wxColour c(im.rgb[p*3],im.rgb[p*3+1],im.rgb[p*3+2],im.HasAlpha()?im.alpha[p]:255);if(mask&&im.masked&&c.GetRGB()==im.mask.GetRGB())continue;Pixel(xx+x,yy+y,c);}}
bool wxDC::Blit(int x,int y,int w,int h,wxDC* src,int sx,int sy,int,bool mask){if(!src||!src->target||!target)return false;auto im=src->target;wxImage crop(w,h);crop.InitAlpha();std::fill(crop.alpha.begin(),crop.alpha.end(),0);for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++)if(sx+xx>=0&&sy+yy>=0&&sx+xx<im->w&&sy+yy<im->h){size_t a=size_t(sy+yy)*im->w+sx+xx,b=size_t(yy)*w+xx;std::copy_n(&im->rgb[a*3],3,&crop.rgb[b*3]);crop.alpha[b]=im->HasAlpha()?im->alpha[a]:255;}crop.mask=im->mask;crop.masked=im->masked;DrawBitmap(wxBitmap(crop),x,y,mask);return true;}
void wxDC::GetTextExtent(const wxString& text,int* w,int* h,int* descent,int* leading,const wxFont* f){auto ft=f?*f:font;float scale=FontScale(ft);int ascent,desc,gap;stbtt_GetFontVMetrics(&fontInfo,&ascent,&desc,&gap);double width=0;auto cps=Codepoints(text);for(size_t i=0;i<cps.size();i++){int adv,bearing;stbtt_GetCodepointHMetrics(&fontInfo,cps[i],&adv,&bearing);width+=adv*scale;if(i+1<cps.size())width+=stbtt_GetCodepointKernAdvance(&fontInfo,cps[i],cps[i+1])*scale;}if(w)*w=std::ceil(width);if(h)*h=std::ceil((ascent-desc)*scale);if(descent)*descent=std::ceil(-desc*scale);if(leading)*leading=std::ceil(gap*scale);}
void wxDC::DrawText(const wxString& text,int x,int y){int tw,th;GetTextExtent(text,&tw,&th);Bounds(x,y);Bounds(x+tw,y+th);float scale=FontScale(font);int asc,desc,gap;stbtt_GetFontVMetrics(&fontInfo,&asc,&desc,&gap);int baseline=y+std::lround(asc*scale);double xpos=x;auto cps=Codepoints(text);for(size_t i=0;i<cps.size();i++){int w,h,xoff,yoff;auto bits=stbtt_GetCodepointBitmap(&fontInfo,0,scale,cps[i],&w,&h,&xoff,&yoff);for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++){int a=bits[yy*w+xx]*textColor.Alpha()/255;Pixel(std::lround(xpos)+xoff+xx,baseline+yoff+yy,wxColour(textColor.Red(),textColor.Green(),textColor.Blue(),a));}stbtt_FreeBitmap(bits,nullptr);int adv,bear;stbtt_GetCodepointHMetrics(&fontInfo,cps[i],&adv,&bear);xpos+=adv*scale;if(i+1<cps.size())xpos+=stbtt_GetCodepointKernAdvance(&fontInfo,cps[i],cps[i+1])*scale;}}

wxImage wxImage::Blur(int radius)const{wxImage out=*this;if(radius<=0)return out;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int sum[3]={},n=0;for(int yy=std::max(0,y-radius);yy<=std::min(h-1,y+radius);yy++)for(int xx=std::max(0,x-radius);xx<=std::min(w-1,x+radius);xx++){for(int c=0;c<3;c++)sum[c]+=rgb[(size_t(yy)*w+xx)*3+c];n++;}for(int c=0;c<3;c++)out.rgb[(size_t(y)*w+x)*3+c]=sum[c]/n;}return out;}
